"""Build a zero-dependency, mobile-friendly SVG template browser."""
from pathlib import Path
import json
root=Path(__file__).parent
items=json.loads((root/'manifest.json').read_text())
payload=json.dumps(items,ensure_ascii=False).replace('</','<\\/')
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Easywurld / Visual Template Library</title><style>
:root{--g:#144D3C;--b:#FBE7C5;--paper:#faf7ef;--line:#c6d4c6}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--g);font-family:Arial,sans-serif}h1,h2{font-family:Georgia,serif}header{background:var(--g);color:var(--b);padding:38px clamp(20px,5vw,80px)}header span{font-size:12px;letter-spacing:.22em;font-weight:700}h1{font-size:clamp(30px,4vw,56px);margin:8px 0 12px}header p{max-width:800px;line-height:1.6;margin:0}.wrap{padding:30px clamp(20px,5vw,80px);max-width:1600px;margin:auto}.warning{border-left:4px solid #A98323;background:#fff5db;padding:14px 18px;line-height:1.5;margin-bottom:25px}.actions{display:flex;flex-wrap:wrap;align-items:end;gap:14px;padding:14px 0 25px}label{font-size:13px;font-weight:700;display:grid;gap:7px}select,input,button{border:1px solid #9db09e;border-radius:3px;background:white;color:var(--g);font-size:15px;padding:10px;min-width:180px}button{cursor:pointer}button[aria-pressed=true]{background:var(--g);color:white}a{color:var(--g)}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:20px}.card{background:white;border:1px solid var(--line);padding:14px;min-width:0}.frame{position:relative;background:#e9e9e1;display:flex;justify-content:center;align-items:center;height:320px;overflow:hidden}.canvas{position:relative;max-width:100%;height:auto}.canvas img{display:block;width:100%;height:100%;object-fit:contain}.frame .overlay{display:none;position:absolute;border:2px dashed #ff6b2d;background:rgba(255,107,45,.10);pointer-events:none}.frame .sticker{display:none;position:absolute;border:2px dashed #6b33dc;background:rgba(107,51,220,.07);pointer-events:none}.show-safe .frame .overlay,.show-safe .frame .sticker{display:block}.card h3{font-family:Georgia,serif;font-size:19px;line-height:1.15;margin:14px 0 5px}.meta{font-size:12px;color:#596d60;line-height:1.5}.pill{font-size:11px;letter-spacing:.1em;text-transform:uppercase}.links{display:flex;gap:15px;margin-top:12px;font-size:13px;font-weight:700}.count{margin:0 0 18px;font-size:13px}.doc-links{display:flex;flex-wrap:wrap;gap:15px;border-top:1px solid var(--line);padding:22px 0;margin-top:35px}@media(max-width:600px){.frame{height:280px}select,input{width:100%}.actions label{width:100%}}</style></head><body>
<header><span>EASYWURLD / SIMPLIFY. OPTIMIZE. GROW.</span><h1>Editorial, by design.</h1><p>11 carousel families, 12 stories, 12 LinkedIn families, TikTok reflows and a reusable component sheet. Every tile opens an actual editable SVG source—not a flattened mockup.</p></header><main class="wrap"><div class="warning"><b>Review library · v1.0 · not approved for publication.</b> Lora/Canva Sans files are not bundled; browser fallback may differ. Orange overlay = internal content-safe rectangle, purple = proposed native story-sticker reserve. These are conservative design aids, not official platform specs. Confirm in the live composer and on a phone. No templates are scheduled.</div>
<div class="actions"><label>Format<select id="kind"><option value="">All formats</option><option>carousel</option><option>story</option><option>LinkedIn</option><option>TikTok photo reflow</option><option>component sheet</option></select></label><label>Series / family<select id="family"><option value="">All families</option></select></label><label>Search<input id="search" type="search" placeholder="diagnosis, cover, opinion…"></label><button id="safe" aria-pressed="false">Show safe areas</button></div><p class="count" id="count"></p><div class="grid" id="grid"></div><div class="doc-links"><a href="01_MASTER_VISUAL_PROMPT.md">Master visual production prompt</a><a href="TEMPLATE_INDEX.md">Template index &amp; editing notes</a><a href="QA_REPORT.md">QA and holds</a></div></main>
<script>const items=__DATA__;const root=document.querySelector('#grid'),kind=document.querySelector('#kind'),family=document.querySelector('#family'),search=document.querySelector('#search'),safe=document.querySelector('#safe');const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));for(const name of [...new Set(items.map(x=>x.family))].sort()){const o=document.createElement('option');o.textContent=name;family.append(o)}function sizeOf(s){return s.split('x').map(Number)}function render(){const q=search.value.toLowerCase();let visible=items.filter(x=>(!kind.value||(kind.value==='LinkedIn'?x.kind.startsWith('LinkedIn'):x.kind===kind.value))&&(!family.value||x.family===family.value)&&(!q||[x.path,x.role,x.family].join(' ').toLowerCase().includes(q)));document.querySelector('#count').textContent=visible.length+' editable source files shown / '+items.length+' total';root.innerHTML=visible.map(x=>{let [w,h]=sizeOf(x.size),[x1,y1,x2,y2]=x.safe,sa=`left:${x1/w*100}%;top:${y1/h*100}%;width:${(x2-x1)/w*100}%;height:${(y2-y1)/h*100}%`,story=x.kind==='story'?`<div class="sticker" style="left:${160/w*100}%;top:${1110/h*100}%;width:${760/w*100}%;height:${280/h*100}%"></div>`:'';return `<article class="card"><div class="frame"><div class="canvas" style="width:min(100%, ${Math.round(320*w/h)}px);aspect-ratio:${w}/${h}"><img src="${E(x.path)}" loading="lazy" alt="${E(x.family+' '+x.role+' editable template')}"><div class="overlay" style="${sa}"></div>${story}</div></div><h3>${E(x.family)}</h3><div class="pill">${E(x.role)} · ${E(x.size)}</div><p class="meta">${E(x.kind)} · v${E(x.version)} · editable SVG sample; final review pending</p><div class="links"><a href="${E(x.path)}" target="_blank" rel="noopener">Open SVG</a><a href="${E(x.path)}" download>Download source</a></div></article>`}).join('')};for(const el of [kind,family,search])el.addEventListener('input',render);safe.onclick=()=>{let on=safe.getAttribute('aria-pressed')!=='true';safe.setAttribute('aria-pressed',String(on));safe.textContent=on?'Hide safe areas':'Show safe areas';document.body.classList.toggle('show-safe',on)};render();</script></body></html>'''
page=html.replace('__DATA__',payload)
(root/'preview.html').write_text(page,encoding='utf-8')
(root/'index.html').write_text(page,encoding='utf-8')
print('Generated preview.html / index.html with',len(items),'editable sources')
